import{_ as i,o as a,c as n,ae as t}from"./chunks/framework.FQ5RHm_v.js";const k=JSON.parse('{"title":"wvke-sdk | Perfekte Anpassung!","titleTemplate":false,"description":"","frontmatter":{"title":"wvke-sdk | Perfekte Anpassung!","titleTemplate":false},"headers":[],"relativePath":"de/index.md","filePath":"de/index.md"}'),s={name:"de/index.md"};function l(r,e,u,d,o,h){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="wvke-sdk" tabindex="-1">wvke-sdk <a class="header-anchor" href="#wvke-sdk" aria-label="Permalink to &quot;wvke-sdk&quot;">​</a></h1><p>wvke-sdk ist ein JavaScript-SDK für die Kommunikation mit Gaming-Peripheriegeräten, einschließlich Tastaturen und Mäusen.</p><p>Basierend auf moderner WebHID-Technologie ermöglicht es die tiefgehende Anpassung und intelligente Steuerung von Tastaturen, Mäusen und anderen Peripheriegeräten. Es beschleunigt die End-to-End-Bereitstellung von Gaming-Peripherieprodukten und eröffnet neue Möglichkeiten im Gaming-Ökosystem. Das Projekt wird vom GDE Game Driver Engine Team entwickelt und gewartet.</p><h2 id="sdk-typen" tabindex="-1">SDK-Typen <a class="header-anchor" href="#sdk-typen" aria-label="Permalink to &quot;SDK-Typen&quot;">​</a></h2><h3 id="⌨️-lineare-tastatur" tabindex="-1">⌨️ Lineare Tastatur <a class="header-anchor" href="#⌨️-lineare-tastatur" aria-label="Permalink to &quot;⌨️ Lineare Tastatur&quot;">​</a></h3><p>Für mechanische Tastaturen entwickelt:</p><ul><li>Tastenzuordnung und Ebenenwechsel</li><li>RGB-Beleuchtungssteuerung</li><li>WebHID-Autorisierung, Geräteliste und Geräteinitialisierung</li><li>RT-Volldurchgangsschalter, Betätigungsweg und Sicherheitszonenanpassung</li><li>Makroaufzeichnung und -wiedergabe</li><li>Abfrageratenanpassung (1KHz-8KHz)</li><li>Systemmodusumschaltung (Windows/Mac)</li></ul><h3 id="🖱️-maus-sdk" tabindex="-1">🖱️ Maus-SDK <a class="header-anchor" href="#🖱️-maus-sdk" aria-label="Permalink to &quot;🖱️ Maus-SDK&quot;">​</a></h3><p>Für Gaming-Mäuse entwickelt:</p><ul><li>DPI-Anpassung (400-16000 DPI)</li><li>Tastenprogrammierung und Makros</li><li>RGB-Beleuchtungsanpassung</li><li>Abhebehöhenanpassung</li><li>Polling-Optimierung</li></ul><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><ul><li>Modernes JavaScript/TypeScript</li><li>WebHID-Hardwarekommunikation</li><li>Vollständige Beleuchtungssteuerungs-APIs</li><li>Tastenzuordnungs- und Makro-APIs</li><li>RT-Travel- und erweiterte Tasten-APIs</li><li>Maus-DPI- und Tastenzuordnungs-APIs</li><li>Allgemeiner benutzerdefinierter Upgrade-Dienst</li><li>Detaillierte API-Dokumentation</li></ul><h2 id="tutorial" tabindex="-1">Tutorial <a class="header-anchor" href="#tutorial" aria-label="Permalink to &quot;Tutorial&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wvke-sdk</span></span></code></pre></div><p>Weitere Details finden Sie in der <a href="/wvke.sdkdoc/docs/de/api/info.html">API-Dokumentation</a>.</p>',15)])])}const c=i(s,[["render",l]]);export{k as __pageData,c as default};
